function getZendeskAiTranslation(key, lang) {
  if (zendeskAiTranslations[lang] && zendeskAiTranslations[lang][key]) {
    return zendeskAiTranslations[lang][key];
  }
  if (zendeskAiTranslations.en && zendeskAiTranslations.en[key]) {
    return zendeskAiTranslations.en[key];
  }
  return null;
}

function applyZendeskAiTranslations(lang) {
  
  let count = 0;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const key = element.getAttribute('data-i18n');
    if (key && (key.startsWith('review.zendesk-ai.') || key.startsWith('review.common.'))) {
      const translation = getZendeskAiTranslation(key, lang);
      if (translation) {
        element.textContent = translation;
        count++;
      }
    }
  });
  
}

document.addEventListener('languageChanged', (e) => {
  const lang = e.detail.language;
  setTimeout(() => applyZendeskAiTranslations(lang), 200);
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyZendeskAiTranslations(currentLang);
  });
} else {
  const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
  applyZendeskAiTranslations(currentLang);
}


